"""Price helpers."""

TAX_RATES = {"standard": 0.2, "reduced": 0.05}


def calc_total(items, tax_rate):
    """Sum quantity * unit price for every item, then add tax."""
    net = sum(qty * price for qty, price in items)
    return round(net * (1 + tax_rate), 2)

